type Validator[T any] func(T) error
func All[T any](vs ...Validator[T]) Validator[T] {           // divide + conquer
    return func(v T) error {
        var errs []error
        for _, check := range vs {
            if err := check(v); err != nil { errs = append(errs, err) }
        }
        return errors.Join(errs...)                          // report all, not the first
    }
}
var Positive = func(n int) error { if n <= 0 { return fmt.Errorf("must be > 0") }; return nil }
